export interface SemaphoreOptions {
    concurrency: number;
}

export class Semaphore {
    private readonly concurrency: number;
    private readonly queue: Array<{ priority: number; resolve: () => void }>;
    private readonly permits: { used: number; waiting: number };

    public constructor(concurrency: number);
    public constructor(options: SemaphoreOptions);
    public constructor(concurrencyOrOptions: number | SemaphoreOptions) {
        if (typeof concurrencyOrOptions === "number") {
            this.concurrency = concurrencyOrOptions;
        } else {
            this.concurrency = concurrencyOrOptions.concurrency;
        }
        this.queue = [];
        this.permits = { used: 0, waiting: 0 };
    }

    public async acquire(priority: number = 0): Promise<void> {
        if (this.permits.used < this.concurrency) {
            this.permits.used++;
            return;
        }

        return new Promise((resolve) => {
            this.permits.waiting++;
            this.queue.push({ priority, resolve });
            this.queue.sort((a, b) => b.priority - a.priority);
        });
    }

    public release(): void {
        if (this.permits.used > 0) {
            this.permits.used--;
        }

        if (this.permits.waiting > 0 && this.permits.used < this.concurrency) {
            this.permits.waiting--;
            this.permits.used++;
            const next = this.queue.shift();
            if (next) {
                next.resolve();
            }
        }
    }

    public get used(): number {
        return this.permits.used;
    }

    public get waiting(): number {
        return this.permits.waiting;
    }

    public get available(): number {
        return this.concurrency - this.permits.used;
    }
}

export interface RateLimiterOptions {
    rateLimit: number;
    rateLimitBurst: number;
}

export class RateLimiter {
    private readonly rateLimit: number;
    private readonly rateLimitBurst: number;
    private tokens: number;
    private lastRefill: number;
    private readonly refillInterval: number;

    public constructor(rateLimit: number, rateLimitBurst: number) {
        this.rateLimit = rateLimit;
        this.rateLimitBurst = rateLimitBurst;
        this.tokens = rateLimitBurst;
        this.lastRefill = Date.now();
        this.refillInterval = 1000 / this.rateLimit;
    }

    public async acquire(weight: number = 1): Promise<boolean> {
        this.refill();

        if (this.tokens >= weight) {
            this.tokens -= weight;
            return true;
        }

        return false;
    }

    public tryAcquire(weight: number = 1): boolean {
        this.refill();
        if (this.tokens >= weight) {
            this.tokens -= weight;
            return true;
        }
        return false;
    }

    private refill(): void {
        const now = Date.now();
        const elapsed = now - this.lastRefill;

        if (elapsed >= this.refillInterval) {
            const refills = Math.floor(elapsed / this.refillInterval);
            this.tokens = Math.min(this.tokens + refills, this.rateLimitBurst);
            this.lastRefill = now;
        }
    }

    public get availableTokens(): number {
        this.refill();
        return this.tokens;
    }
}

export interface ConnectionPoolOptions {
    baseUrl: string;
    maxConnections?: number;
    enableWarmup?: boolean;
    warmupEndpoints?: string[];
    keepAlive?: boolean;
}

export class ConnectionPool {
    private readonly baseUrl: string;
    private readonly maxConnections: number;
    private readonly warmupEndpoints: string[];
    private readonly keepAlive: boolean;
    private connections: Map<string, unknown>;
    private initialized: boolean;

    public constructor(options: ConnectionPoolOptions) {
        this.baseUrl = options.baseUrl;
        this.maxConnections = options.maxConnections ?? 10;
        this.warmupEndpoints = options.warmupEndpoints ?? [];
        this.keepAlive = options.keepAlive ?? true;
        this.connections = new Map();
        this.initialized = false;
    }

    public async initialize(): Promise<void> {
        if (this.initialized) {
            return;
        }

        this.initialized = true;
    }

    public async warmup(): Promise<void> {
        if (this.warmupEndpoints.length === 0) {
            return;
        }

        const endpointsToWarmup = this.warmupEndpoints.slice(0, this.maxConnections);
        for (const endpoint of endpointsToWarmup) {
            try {
                const key = this.getConnectionKey(endpoint);
                this.connections.set(key, {});
            } catch {}
        }
    }

    public async checkHealth(): Promise<boolean> {
        return this.initialized;
    }

    public async destroy(): Promise<void> {
        this.connections.clear();
        this.initialized = false;
    }

    public getConnection(endpoint: string): unknown {
        const key = this.getConnectionKey(endpoint);
        return this.connections.get(key) || null;
    }

    public releaseConnection(endpoint: string): void {
        if (!this.keepAlive) {
            const key = this.getConnectionKey(endpoint);
            this.connections.delete(key);
        }
    }

    public clear(): void {
        this.connections.clear();
    }

    public get size(): number {
        return this.connections.size;
    }

    private getConnectionKey(endpoint: string): string {
        return `${this.baseUrl}${endpoint}`;
    }
}
